from .midi_68k_r26_resident_audio_service import SATURN_MIDI_68K_R26_OWNED_SLOTS, SATURN_MIDI_68K_R26_VOICE_STATE_ADDRESS
from .midi_68k_r26_physical_candidate import SATURN_MIDI_68K_R26_PHASE_DRAINING, SATURN_MIDI_68K_R26_PHASE_ERROR, SATURN_MIDI_68K_R26_PHASE_NOT_STARTED, SATURN_MIDI_68K_R26_PHASE_PASS, SATURN_MIDI_68K_R26_PHASE_PLAYING, SATURN_MIDI_68K_R26_PHASE_VERIFY_STATE, SATURN_MIDI_68K_R26_PHASE_WAIT_BOOT, SATURN_MIDI_68K_R26_TIMEOUT_MARGIN_US, SATURN_MIDI_68K_R26_VERIFY_ACTIVE_NOTE_MISMATCH, SATURN_MIDI_68K_R26_VERIFY_CONTROLLER_MISMATCH, SATURN_MIDI_68K_R26_VERIFY_FINAL_CONTRACT_MISMATCH, SATURN_MIDI_68K_R26_VERIFY_NOT_RUN, SATURN_MIDI_68K_R26_VERIFY_PASS, SATURN_MIDI_68K_R26_VERIFY_SUMMARY_MISMATCH, _render_words
from .midi_68k_stream_service import SATURN_MIDI_68K_STREAM_BATCH_COUNT_OFFSET, SATURN_MIDI_68K_STREAM_CURRENT_INDEX_OFFSET, SATURN_MIDI_68K_STREAM_FLAG_ERROR, SATURN_MIDI_68K_STREAM_FLAGS_OFFSET, SATURN_MIDI_68K_STREAM_LAST_ERROR_OFFSET, SATURN_MIDI_68K_STREAM_MAGIC_OFFSET, SATURN_MIDI_68K_STREAM_SERVICE_ADDRESS, SATURN_MIDI_68K_STREAM_SERVICE_MAGIC, SATURN_MIDI_68K_STREAM_SERVICE_VERSION, SATURN_MIDI_68K_STREAM_TOTAL_HI_OFFSET, SATURN_MIDI_68K_STREAM_TOTAL_LO_OFFSET, SATURN_MIDI_68K_STREAM_VERSION_OFFSET

def render_srk_saturn_midi_68k_r26_physical_proof_source(profile: SaturnMidi68KR26DoubleImpactProfile, *, release_rate: int) -> str:
    if profile.record_count != 9154 or profile.batch_count != 287:
        raise RuntimeError('R26 physical proof is not the accepted Space Spectre profile')
    if profile.capacity.busy_count != 0 or profile.capacity.release_steal_count != 12:
        raise RuntimeError('R26 physical proof voice-pressure profile changed')
    summaries, controllers, active = build_srk_saturn_midi_68k_r24_expected_midi_words(profile)
    timeout = profile.duration_us + SATURN_MIDI_68K_R26_TIMEOUT_MARGIN_US
    last_batch_records = profile.record_count - (profile.batch_count - 1) * 32
    lines = ['#include "srk_saturn_midi_68k_r26_physical_proof.h"', '#include "srk_saturn_midi_68k_hardware_adapter.h"', '#include "srk_saturn_midi_68k_installer.h"', '#include "srk_saturn_midi_68k_r26_resident_audio_service.h"', '#include "srk_saturn_midi_68k_r26_voice_state.h"', '#include "srk_saturn_midi_68k_stream_service.h"', '#include "srk_saturn_midi_mailbox.h"', '', '#define SRK_R26_RAM ((volatile unsigned short *)0x25A00000UL)', f'#define SRK_R26_SERVICE 0x{SATURN_MIDI_68K_STREAM_SERVICE_ADDRESS:08X}UL', f'#define SRK_R26_SERVICE_MAGIC_OFFSET {SATURN_MIDI_68K_STREAM_MAGIC_OFFSET}UL', f'#define SRK_R26_SERVICE_VERSION_OFFSET {SATURN_MIDI_68K_STREAM_VERSION_OFFSET}UL', f'#define SRK_R26_SERVICE_FLAGS_OFFSET {SATURN_MIDI_68K_STREAM_FLAGS_OFFSET}UL', f'#define SRK_R26_CURRENT_INDEX_OFFSET {SATURN_MIDI_68K_STREAM_CURRENT_INDEX_OFFSET}UL', f'#define SRK_R26_BATCH_COUNT_OFFSET {SATURN_MIDI_68K_STREAM_BATCH_COUNT_OFFSET}UL', f'#define SRK_R26_TOTAL_HI_OFFSET {SATURN_MIDI_68K_STREAM_TOTAL_HI_OFFSET}UL', f'#define SRK_R26_TOTAL_LO_OFFSET {SATURN_MIDI_68K_STREAM_TOTAL_LO_OFFSET}UL', f'#define SRK_R26_LAST_ERROR_OFFSET {SATURN_MIDI_68K_STREAM_LAST_ERROR_OFFSET}UL', f'#define SRK_R26_SERVICE_MAGIC 0x{SATURN_MIDI_68K_STREAM_SERVICE_MAGIC:04X}u', f'#define SRK_R26_SERVICE_VERSION {SATURN_MIDI_68K_STREAM_SERVICE_VERSION}u', f'#define SRK_R26_STREAM_ERROR 0x{SATURN_MIDI_68K_STREAM_FLAG_ERROR:04X}u', f'#define SRK_R26_VOICE_ADDRESS 0x{SATURN_MIDI_68K_R26_VOICE_STATE_ADDRESS:08X}UL', f'#define SRK_R26_SUMMARY_ADDRESS 0x{_r24.SATURN_MIDI_68K_STATE_ADDRESS:08X}UL', f'#define SRK_R26_CONTROLLER_ADDRESS 0x{_r24.SATURN_MIDI_68K_CONTROLLER_ADDRESS:08X}UL', f'#define SRK_R26_ACTIVE_ADDRESS 0x{_r24.SATURN_MIDI_68K_ACTIVE_NOTES_ADDRESS:08X}UL', f'#define SRK_R26_TVMD (*(volatile unsigned short *)0x{_r24.SATURN_MIDI_68K_R24_VDP2_TVMD_ADDRESS:08X}UL)', f'#define SRK_R26_TVSTAT (*(volatile unsigned short *)0x{_r24.SATURN_MIDI_68K_R24_VDP2_TVSTAT_ADDRESS:08X}UL)', f'#define SRK_R26_FRT_TCR (*(volatile unsigned char *)0x{_r24.SATURN_MIDI_68K_R24_FRT_TCR_ADDRESS:08X}UL)', f'#define SRK_R26_CLOCK_NTSC_A {_r24.SATURN_MIDI_68K_R24_CLOCK_NTSC_A_HZ}UL', f'#define SRK_R26_CLOCK_NTSC_B {_r24.SATURN_MIDI_68K_R24_CLOCK_NTSC_B_HZ}UL', f'#define SRK_R26_CLOCK_PAL_A {_r24.SATURN_MIDI_68K_R24_CLOCK_PAL_A_HZ}UL', f'#define SRK_R26_CLOCK_PAL_B {_r24.SATURN_MIDI_68K_R24_CLOCK_PAL_B_HZ}UL', f'#define SRK_R26_DURATION_US {profile.duration_us}UL', f'#define SRK_R26_TIMEOUT_US {timeout}UL', f'#define SRK_R26_RELEASE_RATE {release_rate}u', '']
    lines.extend(_render_words('srk_r26_expected_summary', summaries))
    lines.extend(_render_words('srk_r26_expected_controllers', controllers))
    lines.extend(_render_words('srk_r26_expected_active', active))
    lines.extend(('static unsigned short srk_r26_read(unsigned long address)', '{ return SRK_R26_RAM[address >> 1]; }', '', 'static void srk_r26_write(unsigned long address, unsigned short value)', '{ SRK_R26_RAM[address >> 1] = value; }', '', 'static unsigned short srk_r26_service(unsigned long offset)', '{ return srk_r26_read(SRK_R26_SERVICE + offset); }', '', 'static unsigned short srk_r26_mailbox(unsigned long word_index)', '{ return srk_r26_read(SRK_MIDI_MAILBOX_ADDRESS + (word_index * 2UL)); }', '', 'static unsigned short srk_r26_voice(unsigned short word_index)', '{ return srk_r26_read(SRK_R26_VOICE_ADDRESS + ((unsigned long)word_index * 2UL)); }', '', 'static unsigned long srk_r26_select_clock(SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state)', '{', '    unsigned short tvstat = SRK_R26_TVSTAT;', '    unsigned short tvmd = SRK_R26_TVMD;', '    state->telemetry.clock_pal = (unsigned short)(tvstat & 0x0001u);', '    state->telemetry.clock_group_b = (unsigned short)(tvmd & 0x0001u);', '    if(state->telemetry.clock_pal){', '        if(state->telemetry.clock_group_b) return SRK_R26_CLOCK_PAL_B;', '        return SRK_R26_CLOCK_PAL_A;', '    }', '    if(state->telemetry.clock_group_b) return SRK_R26_CLOCK_NTSC_B;', '    return SRK_R26_CLOCK_NTSC_A;', '}', '', 'static int srk_r26_install(void)', '{', '    unsigned long index;', '    for(index=0UL; index<0x0100UL; index+=2UL) srk_r26_write(SRK_MIDI_MAILBOX_ADDRESS + index, 0u);', '    for(index=0UL; index<0x0200UL; index+=2UL) srk_r26_write(SRK_R26_SERVICE + index, 0u);', '    for(index=0UL; index<(unsigned long)SRK_MIDI_68K_R26_PROGRAM_WORD_COUNT; index++)', '        srk_r26_write(SRK_MIDI_68K_R26_PROGRAM_ADDRESS + (index * 2UL),', '            srk_saturn_midi_68k_r26_resident_audio_service_program[index]);', f'    srk_r26_write(SRK_MIDI_68K_RESET_SSP_VECTOR_ADDRESS, (unsigned short)(0x{_r25.SATURN_MIDI_68K_R25_RESIDENT_AUDIO_STACK_ADDRESS:08X}UL >> 16));', f'    srk_r26_write(SRK_MIDI_68K_RESET_SSP_VECTOR_ADDRESS + 2UL, (unsigned short)(0x{_r25.SATURN_MIDI_68K_R25_RESIDENT_AUDIO_STACK_ADDRESS:08X}UL & 0xFFFFUL));', '    srk_r26_write(SRK_MIDI_68K_RESET_PC_VECTOR_ADDRESS, (unsigned short)(SRK_MIDI_68K_R26_PROGRAM_ADDRESS >> 16));', '    srk_r26_write(SRK_MIDI_68K_RESET_PC_VECTOR_ADDRESS + 2UL, (unsigned short)(SRK_MIDI_68K_R26_PROGRAM_ADDRESS & 0xFFFFUL));', '    for(index=0UL; index<(unsigned long)SRK_MIDI_68K_R26_PROGRAM_WORD_COUNT; index++)', '        if(srk_r26_read(SRK_MIDI_68K_R26_PROGRAM_ADDRESS + (index * 2UL)) !=', '           srk_saturn_midi_68k_r26_resident_audio_service_program[index]) return 0;', '    return 1;', '}', '', 'static void srk_r26_capture(SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state)', '{', '    unsigned short total_hi;', '    state->telemetry.flags = srk_r26_mailbox(SRK_MIDI_MB_FLAGS);', '    state->telemetry.read_sequence = srk_r26_mailbox(SRK_MIDI_MB_READ_SEQUENCE);', '    state->telemetry.read_index = srk_r26_mailbox(SRK_MIDI_MB_READ_INDEX);', '    state->telemetry.last_error = srk_r26_mailbox(SRK_MIDI_MB_LAST_ERROR);', '    state->telemetry.stream_flags = srk_r26_service(SRK_R26_SERVICE_FLAGS_OFFSET);', '    state->telemetry.current_index = srk_r26_service(SRK_R26_CURRENT_INDEX_OFFSET);', '    state->telemetry.batch_count = srk_r26_service(SRK_R26_BATCH_COUNT_OFFSET);', '    total_hi = srk_r26_service(SRK_R26_TOTAL_HI_OFFSET);', '    state->telemetry.total_processed = srk_r26_service(SRK_R26_TOTAL_LO_OFFSET);', '    if(total_hi != 0u) state->telemetry.total_processed = 0xFFFFu;', '    state->telemetry.player_sequence = state->player.published_sequence;', '    state->telemetry.player_batch_index = state->player.next_batch_index;', '    state->telemetry.player_complete = state->player.complete;', '    state->telemetry.player_error = state->player.error;', '    state->telemetry.voice_key_on_count = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_KEY_ON_COUNT_WORD);', '    state->telemetry.voice_key_off_count = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_KEY_OFF_COUNT_WORD);', '    state->telemetry.voice_busy_count = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_BUSY_COUNT_WORD);', '    state->telemetry.voice_held_count = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_HELD_COUNT_WORD);', '    state->telemetry.voice_releasing_count = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_RELEASING_COUNT_WORD);', '    state->telemetry.voice_owned_count = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_OWNED_COUNT_WORD);', '    state->telemetry.voice_peak_held = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_PEAK_HELD_WORD);', '    state->telemetry.voice_peak_owned = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_PEAK_OWNED_WORD);', '    state->telemetry.voice_release_cancelled = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_RELEASE_CANCELLED_WORD);', '    state->telemetry.voice_last_error = srk_r26_voice(SRK_MIDI_68K_R26_VOICE_LAST_ERROR_WORD);', '}', '', 'static void srk_r26_restore_frt(SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state)', '{', '    if(state->frt_configured){ SRK_R26_FRT_TCR = state->original_tcr; state->frt_configured = 0u; }', '}', '', 'static int srk_r26_verify_region(unsigned long address, const unsigned short *expected,', '    unsigned short count, unsigned short region, SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state)', '{', '    unsigned short index;', '    unsigned short actual;', '    for(index=0u; index<count; index++){', '        actual = srk_r26_read(address + ((unsigned long)index * 2UL));', '        if(actual != expected[index]){', '            state->telemetry.state_verify_status = region;', '            state->telemetry.mismatch_region = region;', '            state->telemetry.mismatch_index = index;', '            state->telemetry.expected_value = expected[index];', '            state->telemetry.actual_value = actual;', '            return 0;', '        }', '    }', '    return 1;', '}', '', 'static int srk_r26_verify_final_state(SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state)', '{', f'    if(!srk_r26_verify_region(SRK_R26_SUMMARY_ADDRESS, srk_r26_expected_summary, {len(summaries)}u, {SATURN_MIDI_68K_R26_VERIFY_SUMMARY_MISMATCH}u, state)) return 0;', f'    if(!srk_r26_verify_region(SRK_R26_CONTROLLER_ADDRESS, srk_r26_expected_controllers, {len(controllers)}u, {SATURN_MIDI_68K_R26_VERIFY_CONTROLLER_MISMATCH}u, state)) return 0;', f'    if(!srk_r26_verify_region(SRK_R26_ACTIVE_ADDRESS, srk_r26_expected_active, {len(active)}u, {SATURN_MIDI_68K_R26_VERIFY_ACTIVE_NOTE_MISMATCH}u, state)) return 0;', f'    if(state->telemetry.read_sequence != {profile.batch_count}u ||', f'       state->telemetry.read_index != {last_batch_records}u ||', f'       state->telemetry.batch_count != {profile.batch_count}u ||', f'       state->telemetry.total_processed != {profile.record_count}u ||', f'       state->telemetry.voice_key_on_count != {profile.note_on_count}u ||', f'       state->telemetry.voice_key_off_count != {profile.note_off_count}u ||'))
    from .midi_68k_r26_physical_proof_runtime import r26_physical_runtime_lines
    lines.extend(r26_physical_runtime_lines(profile))
    return '\n'.join(lines)
